            ["tip_island_t"] = new[] { "Fortress Island", "要塞島", "要塞岛" },
            ["tip_island"] = new[] { "The fish are after the pearl in the lighthouse's porch. At its door, [E] opens the gate and the fish start swimming in. Down the dock road: the fishmonger buys fish, the smith forges weapons at his bench, the quartermaster keeps the vault (throw anything at its door) and the loadout. Talk to them with [E]. [I] shows the full guide.", "魚群是來搶燈塔門口那顆珍珠的。到門口按 [E] 打開閘門，魚群就會開始游來。往碼頭的路上：魚販收魚、鐵匠在工作台鍛造武器、軍需官管儲藏庫（什麼都能丟進門口）和配裝，按 [E] 跟他們說話。按 [I] 看完整說明。", "鱼群是来抢灯塔门口那颗珍珠的。到门口按 [E] 打开闸门，鱼群就会开始游来。往码头的路上：鱼贩收鱼、铁匠在工作台锻造武器、军需官管储藏库（什么都能丢进门口）和配装，按 [E] 跟他们说话。按 [I] 看完整说明。" },
            ["tip_start_t"] = new[] { "Build time", "建造時間", "建造时间" },
            ["tip_start"] = new[] { "Press [G] to build: walls across the three beach gaps, turrets behind them. The host can press [N] to start early.", "按 [G] 進入建造模式：在三個沙灘缺口擋牆，牆後放砲塔。房主按 [N] 可以提早開始。", "按 [G] 进入建造模式：在三个沙滩缺口挡墙，墙后放炮塔。房主按 [N] 可以提早开始。" },
            ["tip_build_t"] = new[] { "How to build", "怎麼蓋", "怎么盖" },
            ["tip_build"] = new[] { "[hold LMB] to build, let go to cancel and get the money back. [RMB] on a piece opens its menu (upgrade, repair). [hold H] takes it down.", "[按住左鍵] 施工，放開就取消並退錢。看著建築按 [右鍵] 打開選單（升級、修理）；[按住 H] 拆除。", "[按住左键] 施工，放开就取消并退钱。看着建筑按 [右键] 打开菜单（升级、修理）；[按住 H] 拆除。" },
            ["tip_net_t"] = new[] { "Corpses are money", "魚屍就是錢", "鱼尸就是钱" },
            ["tip_net"] = new[] { "Press [F] to take out your hand net and click on dead fish to scoop them: you'll see them pile up in the net. Sell them at the fish stall by the dock with [U]; any fish you throw onto its counter is sold too.", "按 [F] 拿出手網，對著魚屍按 [左鍵] 撈起來，會看到牠們一隻隻堆進網子。拿到碼頭旁的魚攤按 [U] 賣掉；任何魚丟到魚攤櫃台上也會賣掉。", "按 [F] 拿出手网，对着鱼尸按 [左键] 捞起来，会看到它们一只只堆进网子。拿到码头旁的鱼摊按 [U] 卖掉；任何鱼丢到鱼摊柜台上也会卖掉。" },
            ["tip_netFull_t"] = new[] { "Your net is full", "漁網滿了", "渔网满了" },
            ["tip_netFull"] = new[] { "Walk to the fish stall by the dock (follow the glowing marker) and press [U] to sell. [Shift+U] there buys a bigger net.", "走到碼頭旁的魚攤（跟著閃爍的標記），按 [U] 賣掉。在魚攤前按 [Shift+U] 可以升級漁網。", "走到码头旁的鱼摊（跟着闪烁的标记），按 [U] 卖掉。在鱼摊前按 [Shift+U] 可以升级渔网。" },
            ["tip_loot_t"] = new[] { "Gear dropped", "掉裝備了", "掉装备了" },
            ["tip_loot"] = new[] { "The glowing crystal is a piece of gear: walk over it to pick it up. It goes into the team vault.", "發光的水晶是裝備，走過去就撿起來，會存進全隊共用的儲藏庫。", "发光的水晶是装备，走过去就捡起来，会存进全队共用的储藏库。" },
            ["tip_chest_t"] = new[] { "A chest!", "寶箱！", "宝箱！" },
            ["tip_chest"] = new[] { "A chest appeared by the lighthouse. Walk up and press [E] to open it: several pieces of gear (into the vault), fish scales, sometimes a weapon (on the ground by it).", "燈塔旁出現了寶箱，走過去按 [E] 打開：好幾件裝備（直接進儲藏庫）、幾片魚鱗，有時還有武器（掉在寶箱旁邊）。", "灯塔旁出现了宝箱，走过去按 [E] 打开：好几件装备（直接进储藏库）、几片鱼鳞，有时还有武器（掉在宝箱旁边）。" },
            ["tip_scales_t"] = new[] { "Fish scales", "魚鱗", "鱼鳞" },
            ["tip_scales"] = new[] { "The glowing blue flakes are fish scales: walk over them to pick them up (your count is bottom left). Bosses burst into a ring of them, chests have a few, elites drop one now and then, and dismantling gear at the smithy gives some too. Scales rank gear up, enhance legendaries, mod your weapons and expand the vault.", "發光的藍色小片是魚鱗：走過去就撿起來（數量在左下角）。打王會噴一圈、寶箱有幾片、精英怪偶爾掉一片，到鐵匠拆裝備也會給。魚鱗用來升階、強化傳說、改造武器、擴充儲藏庫和裝備格。", "发光的蓝色小片是鱼鳞：走过去就捡起来（数量在左下角）。打王会喷一圈、宝箱有几片、精英怪偶尔掉一片，到铁匠拆装备也会给。鱼鳞用来升阶、强化传说、改造武器、扩充储藏库和装备格。" },
            ["tip_souls_t"] = new[] { "Souls: permanent upgrades", "魂：永久強化", "魂：永久强化" },
            ["tip_souls"] = new[] { "Each new 10-wave record (from wave 10) earns souls; wave 100 pays the big OVER 99 bonus. Spend them at the lighthouse keeper (the old captain by the lighthouse) for permanent upgrades that stay between runs: weapon damage, tower damage, tower upgrade discount, crit, starting money, fish scales and lighthouse health. [I] shows the full guide.", "每次刷新 10 波區間紀錄（從第 10 波開始）都會拿到魂；第 100 波有 OVER 99 大加成。到燈塔旁找船長伯伯（燈塔阿伯）花魂，買跨局保留的永久強化：武器傷害、塔傷害、塔升級折扣、暴擊、起始金錢、魚鱗、燈塔血量。按 [I] 看完整說明。", "每次刷新 10 波区间纪录（从第 10 波开始）都会拿到魂；第 100 波有 OVER 99 大加成。到灯塔旁找船长伯伯（灯塔阿伯）花魂，买跨局保留的永久强化：武器伤害、塔伤害、塔升级折扣、暴击、起始金钱、鱼鳞、灯塔血量。按 [I] 看完整说明。" },
            ["tip_vault_t"] = new[] { "Time to gear up", "去配裝吧", "去配装吧" },
            ["tip_vault"] = new[] { "Everything you picked up is in the vault: the red-roofed shed left of the dock. Talk to the quartermaster [E] and equip it, any time, mid-round too: gear only works once worn. Anything thrown at its door goes in too.", "撿到的裝備都在儲藏庫：碼頭左邊的紅屋頂小屋，跟軍需官說話 [E] 把裝備裝上，隨時都能換（局中也可以），裝上才有效；任何東西丟到門口也會收進去。", "捡到的装备都在储藏库：码头左边的红屋顶小屋，跟军需官说话 [E] 把装备装上，随时都能换（局中也可以），装上才有效；任何东西丢到门口也会收进去。" },
            ["tip_active_t"] = new[] { "Active gear", "主動裝備", "主动装备" },
            ["tip_active"] = new[] { "Press [K] in a round to use active gear (each use spends one), [Shift+K] to switch to another the team has; how many are left shows bottom right.", "開局中按 [K] 用主動道具（用一次少一個），[Shift+K] 換成全隊有的另一個；右下角會顯示還剩幾個。", "开局中按 [K] 用主动道具（用一次少一个），[Shift+K] 换成全队有的另一个；右下角会显示还剩几个。" },
            ["tip_upkeep_t"] = new[] { "Looking after the fort", "照顧你的要塞", "照顾你的要塞" },
            ["tip_upkeep"] = new[] { "No need for build mode: walk up to a turret or wall and look at it. [E] details · [U] upgrade · [J] repair · [hold H] take down (half the money back).", "不用進建造模式：走到砲塔或牆前看著它。[E] 詳情　[U] 升級　[J] 修理　[按住 H] 拆除（退一半的錢）。", "不用进建造模式：走到炮塔或墙前看着它。[U] 升级　[J] 修理　[按住 H] 拆除（退一半的钱）。" },
            ["tip_team_t"] = new[] { "Build together", "一起蓋", "一起盖" },
            ["tip_team"] = new[] { "See a site that says Building? Look at it and hold the mouse to help: every extra builder adds 60% speed.", "看到寫著「施工中」的工地，看著它按住左鍵就能幫忙，每多一人快 60%。", "看到写着「施工中」的工地，看着它按住左键就能帮忙，每多一人快 60%。" },
            ["tip_foeSpitter_t"] = new[] { "Spitter", "砲擊魚", "炮击鱼" },
            ["tip_foeSpitter"] = new[] { "It floats off the beach and spits. Only turrets near the shore reach it; it dives once the landing fish are dead.", "浮在岸邊海上吐水彈。砲塔要放在靠岸的地方才打得到；登陸的魚死光牠就會潛走。", "浮在岸边海上吐水弹。炮塔要放在靠岸的地方才打得到；登陆的鱼死光它就会潜走。" },
            ["tip_foeBomber_t"] = new[] { "Bomber", "自爆河豚", "自爆河豚" },
            ["tip_foeBomber"] = new[] { "It blows up on whatever it touches. Kill it before it gets close, or drop a decoy duck for it.", "碰到牆或人就會爆炸。在牠靠近前打掉，或放誘餌鴨讓牠炸在鴨子上。", "碰到墙或人就会爆炸。在它靠近前打掉，或放诱饵鸭让它炸在鸭子上。" },
            ["tip_foeTank_t"] = new[] { "Tank crab", "坦克蟹", "坦克蟹" },
            ["tip_foeTank"] = new[] { "Tough and breaks walls fast. Upgrade walls to stone or better; AP rounds and sniper towers hurt it most.", "又硬又會拆牆。把牆升到石頭以上，穿甲彈和狙擊塔對牠特別有效。", "又硬又会拆墙。把墙升到石头以上，穿甲弹和狙击塔对它特别有效。" },
            ["tip_foeThief_t"] = new[] { "Thief!", "小偷魚！", "小偷鱼！" },
            ["tip_foeThief"] = new[] { "It hops walls, grabs corpses or money, and runs back to the sea through a beach. Chase it down to get the loot back!", "會跳過牆偷魚屍或錢，再從沙灘逃回海裡。追上去打死牠，就能把贓物拿回來！", "会跳过墙偷鱼尸或钱，再从沙滩逃回海里。追上去打死它，就能把赃物拿回来！" },
            ["tip_foeShield_t"] = new[] { "Shield bearer", "盾牌魚", "盾牌鱼" },
            ["tip_foeShield"] = new[] { "Its shield stops 80% of turret damage from the front. Put turrets at its side, or hit it yourself.", "盾牌擋掉正面 80% 的砲塔傷害。把砲塔放在側面，或自己動手打。", "盾牌挡掉正面 80% 的炮塔伤害。把炮塔放在侧面，或自己动手打。" },
            ["tip_foeDigger_t"] = new[] { "Digger", "鑽地魚", "钻地鱼" },
            ["tip_foeDigger"] = new[] { "It tunnels under the first wall it meets. Keep some turrets or spikes near the lighthouse too.", "碰到牆會從地底鑽過去。燈塔附近也要放一些砲塔或尖刺。", "碰到墙会从地底钻过去。灯塔附近也要放一些炮塔或尖刺。" },
            ["tip_foeHealer_t"] = new[] { "Healer", "治療魚", "治疗鱼" },
            ["tip_foeHealer"] = new[] { "It heals the fish around it. Take it out first!", "會幫附近受傷的魚補血。優先打掉牠！", "会帮附近受伤的鱼补血。优先打掉它！" },
            ["tip_foeSplitter_t"] = new[] { "Splitter", "分裂魚", "分裂鱼" },
            ["tip_foeSplitter"] = new[] { "It bursts into three small fish when it dies: keep some firepower behind the line.", "死掉會裂成 3 隻小魚，後排要留一點火力。", "死掉会裂成 3 只小鱼，后排要留一点火力。" },
            ["tip_foeWarden_t"] = new[] { "Iron-Claw Warden", "鐵鉗典獄長", "铁钳典狱长" },
            ["tip_foeWarden"] = new[] { "A gold ring over a boss means a move you can break: hit it hard (or blow the conch) before the ring closes and it reels, taking +150%.", "王頭上出現金色圓環＝這招可以破：圓環收起前猛打（或吹海螺），牠就會失衡、受到 +150% 傷害。", "王头上出现金色圆环＝这招可以破：圆环收起前猛打（或吹海螺），它就会失衡、受到 +150% 伤害。" },
            ["tip_foeUrchin_t"] = new[] { "Thousand-Needle Urchin", "萬針刺皇", "万针刺皇" },
            ["tip_foeUrchin"] = new[] { "Red on the ground is where it hits next. Its spikes stay stuck in the sand for a while: don't stand on them.", "地上的紅色就是下一招的落點。射出的刺會插在沙裡一陣子，別站上去。", "地上的红色就是下一招的落点。射出的刺会插在沙里一阵子，别站上去。" },
            ["tip_foeAngler_t"] = new[] { "Abyssal Lantern", "深淵提燈", "深渊提灯" },
            ["tip_foeAngler"] = new[] { "When its lantern swells, turn your back on it! Whoever is looking at the flash gets pulled in.", "燈籠變大時轉身背對牠！閃光那一刻正在看牠的人會被吸過去。", "灯笼变大时转身背对它！闪光那一刻正在看它的人会被吸过去。" },
            ["tip_foeSteed_t"] = new[] { "Silver Steed", "白銀天馬", "白银天马" },
            ["tip_foeSteed"] = new[] { "Its charges go straight through walls. Get out of the lane, or break the charge while it rears.", "牠的衝鋒會直接穿過牆。離開通道，或趁牠揚起前蹄時打斷。", "它的冲锋会直接穿过墙。离开通道，或趁它扬起前蹄时打断。" },
            ["tip_foeStonefish_t"] = new[] { "Venom Rock Emperor", "劇毒岩皇", "剧毒岩皇" },
            ["tip_foeStonefish"] = new[] { "Its venom pools eat walls: repair them after. Stone turrets wake up again on their own.", "毒池會腐蝕城牆，事後記得修。被石化的砲塔過一陣子會自己恢復。", "毒池会腐蚀城墙，事后记得修。被石化的炮塔过一阵子会自己恢复。" },
            ["tip_foeSkyfish_t"] = new[] { "Sky Torpedo Admiral", "天翔魚雷提督", "天翔鱼雷提督" },
            ["tip_foeSkyfish"] = new[] { "Sniper towers and mortars reach it in the sky. Break its dive and it crashes down: everyone, go!", "狙擊塔和迫擊砲打得到天上的牠。打斷俯衝牠就會墜落：全員上！", "狙击塔和迫击炮打得到天上的它。打断俯冲它就会坠落：全员上！" },
            ["tip_foeKraken_t"] = new[] { "Crimson Kraken", "深紅克拉肯", "深红克拉肯" },
            ["tip_foeKraken"] = new[] { "It moves between the beaches under the sea. Turrets close to the water reach it; don't let it drag them in.", "牠會在海底換沙灘。靠水邊的砲塔打得到牠，別讓牠把砲塔拖走。", "它会在海底换沙滩。靠水边的炮塔打得到它，别让它把炮塔拖走。" },
            ["tip_foeVoxel_t"] = new[] { "Shattered Pixel King", "碎裂像素王", "碎裂像素王" },
            ["tip_foeVoxel"] = new[] { "Its copies are smaller and weaker: finish them, but save your burst to break its Ctrl+Z.", "分身比較小、比較弱：清掉牠們，但留住爆發去打斷 Ctrl+Z。", "分身比较小、比较弱：清掉它们，但留住爆发去打断 Ctrl+Z。" },
            ["tip_foeKoi_t"] = new[] { "Koi of the Dragon Gate", "登龍錦鯉", "登龙锦鲤" },
            ["tip_foeKoi"] = new[] { "As a dragon its breath sets buildings burning for a while: spread your turrets out.", "化龍後牠的龍息會讓建築持續燃燒：砲塔分散一點擺。", "化龙后它的龙息会让建筑持续燃烧：炮塔分散一点摆。" },
            ["tip_foeEye_t"] = new[] { "The Eye at the End", "終焉之眼", "终焉之眼" },
            ["tip_foeEye"] = new[] { "Save everything for the Last Judgment: when it hangs over the lighthouse, everyone hit it at once.", "把一切留給最後的審判：牠停在燈塔上空時，全員一起打！", "把一切留给最后的审判：它停在灯塔上空时，全员一起打！" },
            ["tipFoot"] = new[] { "[I] full guide · tips can be turned off in Mod Settings (Tips)", "[I] 完整說明 · 提示卡可在 Mod 設定（Tips）關掉", "[I] 完整说明 · 提示卡可在 Mod 设置（Tips）关掉" },
            ["helpHint"] = new[] { "[I] guide", "[I] 說明", "[I] 说明" },
            ["netHow"] = new[] { "[F] hand net · click on dead fish", "[F] 手網 · 對著魚屍按左鍵撈", "[F] 手网 · 对着鱼尸按左键捞" },
            ["markCrate"] = new[] { "Fish stall: sell fish, buy food [E]", "魚攤・賣魚、買烤魚 [E]", "鱼摊・卖鱼、买烤鱼 [E]" },
            ["markVault"] = new[] { "Vault: gear [E] · throw anything at the door to store it", "儲藏庫・裝備 [E]・東西丟到門口就收進去", "储藏库・装备 [E]・东西丢到门口就收进去" },
            ["markSmithy"] = new[] { "Smithy: forge 3 into 1, rank up, mods, buy weapons [E]", "鐵匠鋪・三合一、升階、改造、買武器 [E]", "铁匠铺・三合一、升阶、改造、买武器 [E]" },
