            ["smithSubtitle"] = new[] { "The workbench over the team vault · three of a kind and colour forge into the next colour · what's made goes back into the vault", "全隊儲藏庫的工作台・三個同款同色的鍛成高一階・做好的放回儲藏庫", "全队储藏库的工作台・三个同款同色的锻成高一阶・做好的放回储藏库" },
