            ["smithShopFull"] = new[] { "The vault is full", "倉庫滿了", "仓库满了" },
            ["smithShopNote"] = new[] { "Paid from the crew's money. Weapons are common and go into your hands (three of a kind forge into one rare); active gear [K] goes into the vault and costs more the further the team has got; explosives go into your hands.", "用全隊的錢買。武器是普通的，直接到你手上（三把一樣的可以合成一把稀有）；K 技能直接進倉庫，打得越遠越貴；炸藥直接到你手上。", "用全队的钱买。武器是普通的，直接到你手上（三把一样的可以合成一把稀有）；K 技能直接进仓库，打得越远越贵；炸药直接到你手上。" },
            ["smithShopItemKind"] = new[] { "The game's own explosive", "遊戲本身的炸藥", "游戏本身的炸药" },
            ["smithShopExplosive"] = new[] { "At the game's own shop price. Light it and throw it well away: it blows fish, people and boats about (a stuck boat too), and hurts anyone close, friends included.", "照遊戲商店的價錢賣。點燃後丟遠一點：魚、人、船都會被炸飛（卡住的船也行），旁邊的人會受傷，隊友也會。", "照游戏商店的价钱卖。点燃后丢远一点：鱼、人、船都会被炸飞（卡住的船也行），旁边的人会受伤，队友也会。" },
            ["smithShopLocked"] = new[] { "Sold after beating the wave {0} boss", "打倒第 {0} 波大王後開賣", "打倒第 {0} 波大王后开卖" },
