            ["modNote"] = new[] { "Yours alone, for good: every {0} you hold, any rarity · paid with the team's fish scales", "只屬於你、永久：你拿的每一把{0}（任何稀有度）都算・用全隊的魚鱗付", "只属于你、永久：你拿的每一把{0}（任何稀有度）都算・用全队的鱼鳞付" },
